import{_ as n,o as t,c as a,a5 as i}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"版本控制与团队协作","description":"一个人写项目可以随便改，但多人协作、或想回退到某个版本时，就需要版本控制。读完这一篇，你能正确配置 Unity 项目的 Git，理解 .meta 文件为什么必须提交，并避开多人协作的常见坑。","frontmatter":{"type":"howto","level":"intermediate"},"headers":[],"relativePath":"unity/05-engineering/chapter-05-version-control.md","filePath":"unity/05-engineering/chapter-05-version-control.md"}'),r={name:"unity/05-engineering/chapter-05-version-control.md"};function o(s,e,c,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="版本控制与团队协作" tabindex="-1" data-src-line="2" data-src-file="unity/05-engineering/chapter-05-version-control.md">版本控制与团队协作 <a class="header-anchor" href="#版本控制与团队协作" aria-label="Permalink to &quot;版本控制与团队协作&quot;">​</a></h1><p data-src-line="4" data-src-file="unity/05-engineering/chapter-05-version-control.md">一个人写项目可以随便改，但多人协作、或想回退到某个版本时，就需要版本控制。读完这一篇，你能正确配置 Unity 项目的 Git，理解 <code>.meta</code> 文件为什么必须提交，并避开多人协作的常见坑。</p><h2 id="_1-unity-项目能用-git-吗" tabindex="-1" data-src-line="6" data-src-file="unity/05-engineering/chapter-05-version-control.md">1. Unity 项目能用 Git 吗 <a class="header-anchor" href="#_1-unity-项目能用-git-吗" aria-label="Permalink to &quot;1. Unity 项目能用 Git 吗&quot;">​</a></h2><p data-src-line="8" data-src-file="unity/05-engineering/chapter-05-version-control.md">能，而且推荐。Unity 项目本质上就是一堆文件：脚本（<code>.cs</code>）、场景（<code>.unity</code>）、资源（贴图、模型、音频）和配置。Git 管理这些文件，让你能记录历史、回退版本、多人协作。</p><p data-src-line="10" data-src-file="unity/05-engineering/chapter-05-version-control.md">但 Unity 项目有两个特殊性，处理不好会出问题，下面重点讲。</p><h2 id="_2-哪些文件要忽略" tabindex="-1" data-src-line="12" data-src-file="unity/05-engineering/chapter-05-version-control.md">2. 哪些文件要忽略 <a class="header-anchor" href="#_2-哪些文件要忽略" aria-label="Permalink to &quot;2. 哪些文件要忽略&quot;">​</a></h2><p data-src-line="14" data-src-file="unity/05-engineering/chapter-05-version-control.md">Unity 项目里有些目录是<strong>生成的临时文件</strong>，不该提交。它们体积大、每次打开都会重新生成，提交只会浪费空间还制造冲突。</p><p data-src-line="16" data-src-file="unity/05-engineering/chapter-05-version-control.md">标准做法是加一个 <code>.gitignore</code>，忽略这些目录：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Unity 生成的临时目录</span></span>
<span class="line"><span>[Ll]ibrary/</span></span>
<span class="line"><span>[Tt]emp/</span></span>
<span class="line"><span>[Oo]bj/</span></span>
<span class="line"><span>[Bb]uild/</span></span>
<span class="line"><span>[Bb]uilds/</span></span>
<span class="line"><span>[Ll]ogs/</span></span>
<span class="line"><span>[Uu]ser[Ss]ettings/</span></span>
<span class="line"><span></span></span>
<span class="line"><span># IDE 相关</span></span>
<span class="line"><span>.idea/</span></span>
<span class="line"><span>.vs/</span></span>
<span class="line"><span>.vscode/</span></span></code></pre></div><p data-src-line="34" data-src-file="unity/05-engineering/chapter-05-version-control.md"><strong>提交的内容</strong>应该是：<code>Assets/</code> 目录（脚本、资源、场景）、<code>Packages/</code>（包清单）、<code>ProjectSettings/</code>（项目设置）。<code>Library/</code> 是导入资源的缓存，克隆仓库后 Unity 会自动重新生成，不用提交。</p><h2 id="_3-meta-文件必须提交" tabindex="-1" data-src-line="36" data-src-file="unity/05-engineering/chapter-05-version-control.md">3. <code>.meta</code> 文件必须提交 <a class="header-anchor" href="#_3-meta-文件必须提交" aria-label="Permalink to &quot;3. \`.meta\` 文件必须提交&quot;">​</a></h2><p data-src-line="38" data-src-file="unity/05-engineering/chapter-05-version-control.md">这是 Unity 项目最容易踩的坑。Unity 会为 <code>Assets/</code> 里的每个资源生成一个同名的 <code>.meta</code> 文件，存的是这个资源的<strong>唯一标识符（GUID）</strong> 和导入设置。</p><p data-src-line="40" data-src-file="unity/05-engineering/chapter-05-version-control.md">场景里的引用是靠 GUID 而不是文件名：</p><ul data-src-line="42" data-src-file="unity/05-engineering/chapter-05-version-control.md"><li data-src-line="42" data-src-file="unity/05-engineering/chapter-05-version-control.md">场景里一个物体引用某张贴图，存的是贴图的 GUID。</li><li data-src-line="43" data-src-file="unity/05-engineering/chapter-05-version-control.md">如果 <code>.meta</code> 文件没提交，别人拉取代码后 Unity 会为贴图重新生成一个<strong>不同的 GUID</strong>，导致场景里所有对该贴图的引用丢失（贴图变&quot;丢失&quot;状态）。</li></ul><p data-src-line="45" data-src-file="unity/05-engineering/chapter-05-version-control.md">所以 <strong><code>.meta</code> 文件必须和资源一起提交</strong>，<code>.gitignore</code> 里绝不能忽略 <code>*.meta</code>。</p><h2 id="_4-场景文件的合并冲突" tabindex="-1" data-src-line="47" data-src-file="unity/05-engineering/chapter-05-version-control.md">4. 场景文件的合并冲突 <a class="header-anchor" href="#_4-场景文件的合并冲突" aria-label="Permalink to &quot;4. 场景文件的合并冲突&quot;">​</a></h2><p data-src-line="49" data-src-file="unity/05-engineering/chapter-05-version-control.md">场景文件（<code>.unity</code>）是 YAML 格式，但<strong>极难自动合并</strong>。两个人都改了同一个场景，Git 合并时几乎必然冲突，而且手工解决场景冲突非常痛苦。</p><p data-src-line="51" data-src-file="unity/05-engineering/chapter-05-version-control.md">多人协作的应对策略：</p><ul data-src-line="53" data-src-file="unity/05-engineering/chapter-05-version-control.md"><li data-src-line="53" data-src-file="unity/05-engineering/chapter-05-version-control.md"><strong>拆分场景</strong>：把不同功能放在不同场景，或用<strong>预制体</strong>拆分——每个人改自己的预制体，只在装配场景时合并。</li><li data-src-line="54" data-src-file="unity/05-engineering/chapter-05-version-control.md"><strong>分工避免同时改场景</strong>：约定谁负责哪个场景，避免并行编辑同一个场景。</li><li data-src-line="55" data-src-file="unity/05-engineering/chapter-05-version-control.md"><strong>用预制体代替场景编辑</strong>：把可复用的东西做成预制体（前面讲过），预制体作为独立文件提交，冲突概率远低于场景。</li></ul><h2 id="_5-一个最小-git-配置流程" tabindex="-1" data-src-line="57" data-src-file="unity/05-engineering/chapter-05-version-control.md">5. 一个最小 Git 配置流程 <a class="header-anchor" href="#_5-一个最小-git-配置流程" aria-label="Permalink to &quot;5. 一个最小 Git 配置流程&quot;">​</a></h2><ol data-src-line="59" data-src-file="unity/05-engineering/chapter-05-version-control.md"><li data-src-line="59" data-src-file="unity/05-engineering/chapter-05-version-control.md">初始化仓库：<code>git init</code>。</li><li data-src-line="60" data-src-file="unity/05-engineering/chapter-05-version-control.md">添加 <code>.gitignore</code>（内容见第 2 节）。</li><li data-src-line="61" data-src-file="unity/05-engineering/chapter-05-version-control.md">确保 <code>.meta</code> 文件被跟踪（不要忽略 <code>*.meta</code>）。</li><li data-src-line="62" data-src-file="unity/05-engineering/chapter-05-version-control.md">提交 <code>Assets/</code>、<code>Packages/</code>、<code>ProjectSettings/</code> 和 <code>.gitignore</code>。</li><li data-src-line="63" data-src-file="unity/05-engineering/chapter-05-version-control.md">推送到远程仓库（GitHub 等）。</li></ol><p data-src-line="65" data-src-file="unity/05-engineering/chapter-05-version-control.md">首次提交后，验证一下：在另一台机器（或另一个目录）<code>git clone</code>，用 Unity Hub 打开，确认资源引用正常、没有&quot;丢失&quot;的资源。如果引用丢失，多半是 <code>.meta</code> 没提交。</p><h2 id="_6-协作的常见坑" tabindex="-1" data-src-line="67" data-src-file="unity/05-engineering/chapter-05-version-control.md">6. 协作的常见坑 <a class="header-anchor" href="#_6-协作的常见坑" aria-label="Permalink to &quot;6. 协作的常见坑&quot;">​</a></h2><table tabindex="0"><thead data-src-line="69" data-src-file="unity/05-engineering/chapter-05-version-control.md"><tr data-src-line="69" data-src-file="unity/05-engineering/chapter-05-version-control.md"><th>问题</th><th>原因</th><th>处理</th></tr></thead><tbody data-src-line="71" data-src-file="unity/05-engineering/chapter-05-version-control.md"><tr data-src-line="71" data-src-file="unity/05-engineering/chapter-05-version-control.md"><td>资源引用丢失（Missing）</td><td><code>.meta</code> 文件没提交</td><td>补提交 <code>.meta</code>，或重新建立引用</td></tr><tr data-src-line="72" data-src-file="unity/05-engineering/chapter-05-version-control.md"><td>场景合并冲突</td><td>两人同时改同一场景</td><td>拆预制体、分工避免并行改场景</td></tr><tr data-src-line="73" data-src-file="unity/05-engineering/chapter-05-version-control.md"><td>仓库体积暴涨</td><td><code>Library/</code> 等临时目录被提交</td><td>加 <code>.gitignore</code> 并从仓库移除</td></tr><tr data-src-line="74" data-src-file="unity/05-engineering/chapter-05-version-control.md"><td>换机器后打不开</td><td>项目版本不一致</td><td>团队统一 Unity 版本（用 Hub 锁定）</td></tr></tbody></table><h2 id="_7-下一步" tabindex="-1" data-src-line="76" data-src-file="unity/05-engineering/chapter-05-version-control.md">7. 下一步 <a class="header-anchor" href="#_7-下一步" aria-label="Permalink to &quot;7. 下一步&quot;">​</a></h2><p data-src-line="78" data-src-file="unity/05-engineering/chapter-05-version-control.md">工程实践到此结束。下一篇进入进阶与发布，先解决&quot;怎么把游戏打包给玩家&quot;的问题：<a href="./../06-advanced/chapter-01-build-publish.html">跨平台打包与发布</a>。</p>`,26)])])}const u=n(r,[["render",o]]);export{h as __pageData,u as default};
